export function sharedWorkspace({getLocal,onLoad,onRole,onError,onStatus=()=>{},onConflict=()=>{}}){
 let revision=0,base=null,ready=false,pending=false,role='viewer',lastRefresh='',failed=null;
 const prefix='frc7028-pending-save-v2';let key=prefix+':'+crypto.randomUUID();function recoveryKey(){for(let n=0;n<localStorage.length;n++){const k=localStorage.key(n);if(k===prefix||k.startsWith(prefix+':'))return k;}return null;}
 function status(label){onStatus(label,lastRefresh);}
 async function request(method,path,body){let r;try{r=await fetch(path,{method,headers:{'Content-Type':'application/json'},cache:'no-store',...(body?{body:JSON.stringify(body)}:{})});}catch{throw Object.assign(Error('Offline. Editing is unavailable; your attempted save is retained.'),{offline:true});}let d;try{d=await r.json();}catch{throw Error('Server response could not be read. Retry your saved changes.');}if(!r.ok)throw Object.assign(Error(d.error||'Save failed.'),{data:d,status:r.status});return d;}
 function loaded(d){revision=d.revision;base=structuredClone(d.workspace);ready=true;role=d.role||(d.isAdmin?'admin':'member');onRole(d.isAdmin,role,d.identity);lastRefresh=new Date().toISOString();onLoad(d.workspace);}
 async function start(){status('Connecting');try{if(!localStorage.getItem('frc7028-before-shared-migration'))localStorage.setItem('frc7028-before-shared-migration',JSON.stringify(getLocal()));let d=await request('GET','/api/workspace');if(!d.initialized&&d.isAdmin)d=await request('PUT','/api/workspace',{workspace:getLocal(),baseRevision:0});loaded(d);const recover=recoveryKey();if(recover)key=recover;const stored=recover?localStorage.getItem(recover):null;failed=stored?JSON.parse(stored):null;ready=!failed;if(failed)status('Changes waiting to sync');else status('Saved');}catch(e){ready=false;status(e.offline?'Offline':'Failed to connect');onError(e.message);}}
 async function transmit(body){pending=true;ready=false;status('Saving');try{const d=await request('PUT','/api/workspace',body);localStorage.removeItem(key);failed=null;loaded(d);status('Saved');}catch(e){failed=body;ready=false;status(e.status===409?'Conflicting edits':e.offline?'Offline · changes waiting to sync':'Failed save · retry available');onError(e.message);if(e.status===409&&e.data?.workspace)onConflict(e.data,body);}finally{pending=false;}}
 function save(workspace,{restore=false}={}){if(!ready||pending||role==='viewer'){onError(role==='viewer'?'Viewer access is read-only.':'Resolve the pending save or reconnect before editing.');return false;}const body={workspace:structuredClone(workspace),baseWorkspace:base,baseRevision:revision,...(restore?{action:'restore'}:{})};try{key=prefix+':'+crypto.randomUUID();localStorage.setItem(key,JSON.stringify(body));localStorage.setItem('frc7028-unsynced-backup',JSON.stringify(workspace));}catch{onError('The recovery copy could not be saved. Free device storage before editing.');return false;}void transmit(body);return true;}
 async function retry(){if(pending)return;if(failed)await transmit(failed);else await start();}
 async function resolve(workspace,remote,remoteRevision,restore=false){const body={workspace,baseWorkspace:remote,baseRevision:remoteRevision,...(restore?{action:'restore'}:{})};localStorage.setItem(key,JSON.stringify(body));await transmit(body);}

 const timer=setInterval(async()=>{if(!ready||pending||document.hidden||document.querySelector('dialog[open]'))return;try{const d=await request('GET','/api/workspace');if(d.revision!==revision)loaded(d);else lastRefresh=new Date().toISOString();status('Saved');}catch(e){ready=false;status(e.offline?'Offline':'Refresh failed');}},10000);
 window.addEventListener('online',()=>{if(!failed)start();else status('Changes waiting to sync');});window.addEventListener('offline',()=>{ready=false;status('Offline · editing unavailable');});window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});
 return {start,save,retry,resolve,get ready(){return ready&&!pending&&role!=='viewer';}};
}
